/*
 * backfill-guest-events — a realistic fortnight of guest recommendation activity
 * for the demo, so the Recommendation Performance page (Phase 0 recsys) has a
 * funnel to show instead of an honest-but-empty screen.
 *
 * This is DEMO SEED DATA, in the same spirit as backfill-history / backfill-
 * guest-visits: it is generated by a script, clearly marked (every session id is
 * prefixed `seed-`), and deterministic (a fixed PRNG seed) so the same fortnight
 * reproduces on every run. It does not touch orders, payments or revenue — only
 * the guest_events log the guest app writes at runtime. Real events posted by the
 * live app (session ids are UUIDs) sit alongside these untouched.
 *
 * The shape is a believable funnel with real drop-off: most sessions see picks,
 * fewer add a dish, fewer add a *recommended* dish, fewer still order — and a
 * scatter of refine/capped rejections. Reco-driven adds point at real menu items,
 * so the page's margin join lands them in this menu's own quadrants.
 *
 * Idempotent: clears this restaurant's `seed-` sessions first, then rewrites.
 *
 * Usage: node scripts/backfill-guest-events.js [restaurantId] [--sessions 60] [--days 14]
 */
const db = require('../src/shared/db');

const DAY_MS = 24 * 60 * 60 * 1000;

function flag(name, fallback) {
  const i = process.argv.indexOf(`--${name}`);
  return i > -1 && process.argv[i + 1] ? process.argv[i + 1] : fallback;
}

// Small deterministic PRNG (mulberry32) — a fixed seed makes the demo repeatable.
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const FUNNEL_STEPS = [
  ['welcome', 'Welcome', '/'],
  ['details', 'Details', '/walk-in'],
  ['table', 'Table', '/members'],
  ['tastes', 'Tastes', '/preferences'],
  ['picks', 'Picks', '/recommendations'],
];

async function main() {
  const restaurantId =
    (process.argv[2] && !process.argv[2].startsWith('--') ? process.argv[2] : null) ||
    (await db.query(`SELECT id FROM restaurants WHERE name = 'Demo Restaurant' LIMIT 1`)).rows[0]?.id;
  if (!restaurantId) throw new Error('No restaurant id given and no "Demo Restaurant" found');

  const sessionCount = Number(flag('sessions', 140));
  const days = Number(flag('days', 14));

  // Recommendable dishes: real menu items, biased toward the best sellers so the
  // reco adds resemble what the recommender actually surfaces. Falls back to any
  // available items when there is no sales history.
  const { rows: dishes } = await db.query(
    `SELECT mi.id, mi.name,
            COALESCE(SUM(oi.quantity), 0)::int AS sold
       FROM menu_items mi
       LEFT JOIN order_items oi ON oi.menu_item_id = mi.id AND oi.status <> 'cancelled'
      WHERE mi.restaurant_id = $1 AND mi.available = true AND mi.archived_at IS NULL
      GROUP BY mi.id, mi.name
      ORDER BY sold DESC
      LIMIT 16`,
    [restaurantId],
  );
  if (dishes.length === 0) throw new Error('No available menu items to recommend');

  const rand = mulberry32(0x0000c00c);
  const pick = (arr) => arr[Math.floor(rand() * arr.length)];

  // Clear prior seed rows so a re-run is deterministic.
  await db.query(
    `DELETE FROM guest_events WHERE restaurant_id = $1 AND session_id LIKE 'seed-%'`,
    [restaurantId],
  );

  const rows = [];
  const now = Date.now();

  for (let s = 0; s < sessionCount; s += 1) {
    const sessionId = `seed-${String(s).padStart(3, '0')}`;
    const startedAgoMs = (rand() * days) * DAY_MS + rand() * 6 * 3600 * 1000;
    let t = now - startedAgoMs;
    let seq = 0;
    const push = (event, source, dish, props) => {
      t += 4000 + rand() * 40000; // a few seconds to a minute between steps
      rows.push({
        sessionId, seq: seq++, event,
        source: source || null,
        menuItemId: dish?.id || null,
        dishName: dish?.name || null,
        props: props || {},
        occurredAt: new Date(t),
      });
    };

    // The set of dishes shown this round — biased toward the head of the list
    // (the picks that actually surface), so per-dish impressions track adds.
    const shownDishes = [];
    for (let k = 0; k < 6; k += 1) shownDishes.push(dishes[Math.floor(rand() * rand() * dishes.length)]);
    const shownIds = [...new Set(shownDishes.map((d) => d.id))];
    const entry = pick(['walkin', 'reservation', 'join']);
    const groupType = pick(['date', 'family', 'friends', 'business', 'solo']);
    const partySize = 1 + Math.floor(rand() * 6);

    // Everyone walks the onboarding steps up to picks.
    for (const [step, label, route] of FUNNEL_STEPS) push('funnel_step', null, null, { step, label, route });
    push('recommendations_shown', null, null, { round: 0, count: 6, entry, groupType, partySize, dishIds: shownIds });

    // A quarter of tables refine the picks once (a second shown round). Refiners
    // are a bit less likely to convert — the first picks weren't quite right — but
    // they still add and order, so the refine read isn't a pure-rejecter artifact.
    const refined = rand() < 0.25;
    if (refined) {
      push('recommendations_shown', null, null, { round: 1, count: 6, entry, groupType, partySize, dishIds: shownIds });
      if (rand() < 0.5) push('reco_rejected', null, null, { reason: 'refine', round: 1 });
    }

    // ~70% of tables add at least one dish; refiners a little less.
    let recoAdds = 0;
    let manualAdds = 0;
    if (rand() < (refined ? 0.6 : 0.72)) {
      const adds = 1 + Math.floor(rand() * 3);
      for (let a = 0; a < adds; a += 1) {
        const fromReco = rand() < 0.64; // most adds come from a pick, some from browsing
        const dish = fromReco ? pick(shownDishes) : pick(dishes);
        push('dish_added', fromReco ? 'reco' : 'manual', dish, { dishId: dish.id, from: fromReco ? 'reco' : 'manual', qty: 1 });
        if (fromReco) recoAdds += 1; else manualAdds += 1;
        if (rand() < 0.12) push('dish_removed', fromReco ? 'reco' : 'manual', dish, { dishId: dish.id, from: fromReco ? 'reco' : 'manual', qty: 0 });
      }
    } else if (rand() < 0.4) {
      push('reco_rejected', null, null, { reason: 'capped', round: refined ? 1 : 0 });
    }
    const addedCount = recoAdds + manualAdds;

    // Sessions that added anything mostly order. recoShare is the real fraction of
    // items that came from a pick, so a manual-only table books a non-reco order —
    // giving revenue attribution and the AOV-lift comparison genuine both sides.
    if (addedCount > 0 && rand() < (refined ? 0.6 : 0.68)) {
      const items = addedCount;
      const usedReco = recoAdds > 0;
      const perItem = usedReco ? 210 + rand() * 320 : 170 + rand() * 220; // reco tables order a touch richer
      const total = Math.round(items * perItem * 100) / 100;
      const recoShare = Math.round((recoAdds / items) * 100) / 100; // the true fraction
      push('order_placed', null, null, { items, total, recoShare, refineRounds: refined ? 1 : 0 });
    }
  }

  // Bulk insert in chunks.
  const CHUNK = 200;
  let inserted = 0;
  for (let i = 0; i < rows.length; i += CHUNK) {
    const slice = rows.slice(i, i + CHUNK);
    const values = [];
    const params = [];
    slice.forEach((r, j) => {
      const b = j * 8;
      values.push(`($${b + 1}, $${b + 2}, $${b + 3}, $${b + 4}, $${b + 5}, $${b + 6}, $${b + 7}::jsonb, $${b + 8})`);
      params.push(restaurantId, r.sessionId, r.seq, r.event, r.source, r.menuItemId, JSON.stringify(r.props), r.occurredAt);
    });
    const { rowCount } = await db.query(
      `INSERT INTO guest_events
         (restaurant_id, session_id, seq, event, source, menu_item_id, props, occurred_at)
       VALUES ${values.join(', ')}
       ON CONFLICT (restaurant_id, session_id, seq) DO NOTHING`,
      params,
    );
    inserted += rowCount;
  }

  console.log(`Seeded ${inserted} guest events across ${sessionCount} sessions over ${days} days.`);
}

main()
  .then(() => process.exit(0))
  .catch((e) => { console.error(e.message); process.exit(1); });
